(()=>{
 const previousMapping=statusMappingPage;
 statusMappingPage=function(){const template=document.createElement('template');template.innerHTML=previousMapping();const root=template.content;root.querySelector('.status-panel-head p').textContent='用途：完成判断、开发/测试历时、风险和通知。';const header=root.querySelector('.cfg-section-head'),edit=root.querySelector('[data-status-edit]'),audit=root.querySelector('.status-empty');header.append(edit);root.querySelector('.status-panel-head h2').remove();root.querySelector('.cfg-section-body.note').append(audit);const summary=root.querySelector('.status-summary');if(summary.lastElementChild.textContent===summary.children[2].textContent.replace(/\d+ 个/,''))summary.lastElementChild.remove();root.querySelector('.cfg-section-body.note').textContent='未映射：工单继续同步，受影响能力暂停。恢复：保存映射后，须经同步、计算或校验确认。';return template.innerHTML};
 cfgImpact=function(){const s=state.statusMapping,r=s.recovery,missing=s.mappings.filter(x=>!x.semantic),restored=r.phase==='restored',canValidate=['pending','failed'].includes(r.phase);const next=missing.length?'补齐映射并保存':restored?'查看异常与审计':'验证恢复结果';return `<section class="semantic-current"><div class="semantic-status-head"><div><div class="semantic-eyebrow">当前状态</div><h2>${statusRecoveryLabel()}</h2></div><span class="pill ${restored?'green':'amber'}">${restored?'验证通过（模拟）':missing.length?missing.length+' 个状态未映射':'映射已补齐，仍需验证'}</span></div><p class="semantic-message" role="status" aria-live="polite">${cfgSafe(r.message)}</p><dl class="semantic-facts"><div><dt>关联异常</dt><dd>EX-101</dd></div><div><dt>演示影响范围</dt><dd>当前工作流 · 4 张核心专业子单</dd></div><div><dt>受影响能力</dt><dd>${restored?'已恢复（模拟）':'完成判断、开发/测试历时、风险和通知暂停'}</dd></div><div><dt>下一步</dt><dd>${next}</dd></div></dl></section><div class="semantic-recovery-grid"><section class="semantic-card"><header><h2>待处理问题</h2><span class="tag">${missing.length} 项</span></header>${missing.length?`<ul class="semantic-missing">${missing.map(x=>`<li><div><b>${cfgSafe(x.name)}</b><span class="cfg-mono">${cfgSafe(x.id)}</span></div><span class="pill amber">待映射</span></li>`).join('')}</ul><p class="semantic-note">未映射工单继续同步，受影响的完成判断、历时、风险和通知暂停。</p>`:`<div class="semantic-empty">${restored?'映射与模拟验证已完成。':'无未映射状态，等待验证恢复。'}</div>`}<button class="${missing.length?'primary':'ghost'}" type="button" data-status-edit>编辑映射</button></section><section class="semantic-card"><header><h2>验证恢复</h2></header><div class="semantic-verification-note"><span>执行条件</span><p>保存映射后可验证；全部映射补齐后才可验证成功。</p></div><div class="semantic-verify-actions"><button class="${missing.length?'ghost':'primary'}" type="button" data-status-validate="success" ${!canValidate||missing.length?'disabled':''}>模拟验证成功</button><button class="ghost" type="button" data-status-validate="failure" ${!canValidate?'disabled':''}>模拟验证失败</button></div><p class="semantic-note">失败可重试；重新保存映射后，须重新验证。验证成功仅移出对应待处理异常，过程记录保留。</p><button class="link" data-page="anomalies">打开异常与审计 →</button></section></div><div class="semantic-demo">当前项目：${cfgSafe(s.project)} · 工作流：${cfgSafe(s.workflow)}<br>演示说明：仅当前会话，不连接 Teambition，不执行真实同步、计算或投递。</div>${statusMappingDialog()}`};
 const previousDialog=statusMappingDialog;statusMappingDialog=function(){const html=previousDialog();if(!html)return html;const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.status-impact').textContent='影响：完成判断、开发/测试历时、风险和通知。保存后待验证，异常不会直接关闭。原始状态 ID、名称和历史保留。';return t.innerHTML};
 function decorate(){document.body.classList.toggle('status-d',state.page==='config'&&state.cfg.space==='status')}
 const base=render;render=function(){base();decorate()};const params=new URLSearchParams(location.search);if(params.get('page')==='config'&&params.has('statusTab')){state.cfg.space='status';state.cfg.tab=params.get('statusTab')==='impact'?'impact':'mapping';render()}else decorate();
})();
